// 代表题 LC1：唯一一对下标，nums[i] + nums[j] = target。
// 表里只放已经扫过的值。先查 need 再放入当前值，这样 x + x = target 不会用到同一个下标。
// 换题：要全部下标对时不要 return，把 {j, i} 收进列表；值有重复时仍然先查后放。
static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> idx = new HashMap<>();
    for (int i = 0;
    i < nums.length;
    i++) {
        int need = target - nums[i];
        Integer j = idx.get(need);
        if (j != null) {
            return new int[]{
                j, i
            }
            ;
        }
        idx.put(nums[i], i);
    }
    return new int[0];
}

// 代表题 LC49：异位词互为同一组。key 用排序后的字符串。
// char[] 不能直接当 key；要 new String(cs)。Arrays.toString 带括号和逗号，会把内容不同的数组收成难读的 key。
// 换题：只有小写字母时，可改成 26 个计数再用分隔符拼起来。字母次数可能 ≥10，分隔符不能省，否则 1 和 1 会与 11 撞 key。
static List<List<String>> groupAnagrams(String[] strs) {
    Map<String, List<String>> groups = new HashMap<>();
    for (String s : strs) {
        char[] cs = s.toCharArray();
        Arrays.sort(cs);
        String key = new String(cs);
        groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
    }
    return new ArrayList<>(groups.values());
}

