import java.util.*;
class Solution {
    public int[] twoSum(int[] nums, int target) {
        // 已见数值 -> 下标，供后面的数来查配对
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0;
        i < nums.length;
        i++) {
            int need = target - nums[i];
            // 先查再放入，避免同一下标被用两次
            if (seen.containsKey(need)) {
                return new int[]{
                    seen.get(need), i
                }
                ;
            }
            seen.put(nums[i], i);
        }
        // 题意保证有唯一答案，此处只是补齐返回
        return new int[0];
    }
}

import java.util.*;
class Solution {
    public List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String word : strs) {
            int[] counts = new int[26];
            for (char c : word.toCharArray()) {
                counts[c - 'a']++;
            }
            // 频次数组与字符顺序无关，相同频次即异位词
            String key = Arrays.toString(counts);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(word);
        }
        return new ArrayList<>(groups.values());
    }
}

import java.util.*;
class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }
        int longest = 0;
        for (int num : set) {
            // 没有可表示的前驱才是一段的左端点，避免重复扩展
            boolean hasPrevious = num != Integer.MIN_VALUE && set.contains(num - 1);
            if (hasPrevious) continue;
            int current = num;
            int length = 1;
            // 停在 MAX_VALUE，防止 +1 回绕
            while (current != Integer.MAX_VALUE && set.contains(current + 1)) {
                current++;
                length++;
            }
            longest = Math.max(longest, length);
        }
        return longest;
    }
}
